(async()=>{
const NS='http://www.w3.org/2000/svg';
const el=(tag,attrs={},text)=>{const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n};
const svg=(label)=>el('svg',{viewBox:'0 0 480 300',role:'img','aria-label':label});
const fmt=new Intl.NumberFormat('en-AU',{maximumFractionDigits:1});
const describe=(n,text,id)=>{n.setAttribute('tabindex','0');n.append(el('title',{},text));for(const e of ['mouseenter','focus'])n.addEventListener(e,()=>document.getElementById(id).textContent=text)};
try{
const response=await fetch('assets/project-charts.json');if(!response.ok)throw Error('Data unavailable');const data=await response.json();
const select=document.getElementById('emissions-year');for(const y of Object.keys(data.emissions)){const o=document.createElement('option');o.value=y;o.textContent=y;select.append(o)}select.value=Object.keys(data.emissions).at(-1);
function emissions(){const year=select.value;const rows=Object.entries(data.emissions[year]).filter(([k])=>k&&k!=='NA').sort((a,b)=>b[1]-a[1]).slice(0,5);const chart=svg(`Top five industries by water emissions in ${year}`);const max=Math.max(...rows.map(x=>x[1]),1);rows.forEach(([name,v],i)=>{const y=18+i*51;chart.append(el('text',{x:0,y:y+12},name));const bar=el('rect',{x:0,y:y+20,width:Math.max(2,v/max*365),height:15,rx:3,fill:['#354f31','#587847','#7e995c','#a5b97c','#cad6ae'][i]});describe(bar,`${name}: ${fmt.format(v)} kg (${year})`,'emissions-detail');chart.append(bar,el('text',{x:Math.max(2,v/max*365)+8,y:y+32,class:'value'},new Intl.NumberFormat('en-AU',{notation:'compact',maximumSignificantDigits:3}).format(v)))});chart.append(el('text',{x:0,y:290},'Reported water emissions · kg (K = thousand, M = million)'));document.getElementById('emissions-chart').replaceChildren(chart);document.getElementById('emissions-detail').textContent=`${year} · Hover or focus a bar for its value.`}
select.addEventListener('change',emissions);emissions();
const rows=data.finance,chart=svg('Manchester United revenue and annual result, 2020–2024, in million pounds');const left=48,right=455,top=20,bottom=260;const yMin=-200,yMax=700;const x=i=>left+i*(right-left)/(rows.length-1);const y=v=>bottom-(v-yMin)/(yMax-yMin)*(bottom-top);
for(const v of [-200,0,200,400,600]){chart.append(el('line',{x1:left,x2:right,y1:y(v),y2:y(v),stroke:v===0?'#adb89f':'#e6e8dd','stroke-dasharray':v===0?'0':'3 4'}),el('text',{x:left-8,y:y(v)+4,'text-anchor':'end'},String(v)))}
for(const[key,color,label]of [['revenue','#49683b','Revenue'],['loss','#bb6654','Annual result']]){chart.append(el('path',{d:rows.map((r,i)=>`${i?'L':'M'}${x(i)},${y(r[key])}`).join(' '),fill:'none',stroke:color,'stroke-width':3}));rows.forEach((r,i)=>{const dot=el('circle',{cx:x(i),cy:y(r[key]),r:5,fill:color,stroke:'#fff','stroke-width':2});describe(dot,`${r.year} · ${label}: £${fmt.format(r[key])}m`,'finance-detail');chart.append(dot)})}rows.forEach((r,i)=>chart.append(el('text',{x:x(i),y:283,'text-anchor':'middle'},r.year)));chart.append(el('text',{x:0,y:12},'£m'));document.getElementById('finance-chart').replaceChildren(chart);
// Replace the two illustrative project covers with real chart previews.
for(const[index,id]of [[1,'emissions-chart'],[2,'finance-chart']]){const project=document.querySelectorAll('.project')[index];if(!project)continue;const card=project.querySelector('.art');if(!card)continue;const image=document.getElementById(id).querySelector('svg').cloneNode(true);image.removeAttribute('role');image.setAttribute('aria-hidden','true');image.querySelectorAll('[tabindex]').forEach(n=>n.removeAttribute('tabindex'));card.querySelector('svg').replaceWith(image);card.classList.add('real-chart')}
}catch(e){for(const id of ['emissions-detail','finance-detail'])document.getElementById(id).textContent='Chart data could not load. Please refresh the page.'}
})();
